# Découpez votre code en fonctions

def moyenne(nombres):
    """Calcule la moyenne d'une liste de nombres."""
    if not nombres:
        raise ValueError("La liste ne peut pas être vide")
    return sum(nombres) / len(nombres)

def mention(note):
    """Retourne le classement en fonction de la note."""
    if note >= 16:
        return "Félicitations du jury"
    elif note >= 14:
        return "Très bien"
    elif note >= 12:
        return "Bien"
    elif note >= 10:
        return "Assez bien"
    elif note >= 8:
        return "Passable"
    else:
        return "Insuffisant"

# Exemples
print(moyenne([10, 12, 14, 16]))  # 13.0
print(mention(15)))  # Très bien
print(mention(9)))  # Assez bien
